import{_ as t,H as a,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const G=JSON.parse('{"title":"01 | RAG的场景及技术原理","description":"","frontmatter":{},"headers":[{"level":2,"title":"RAG 技术的定义","slug":"rag-技术的定义","link":"#rag-技术的定义","children":[]},{"level":2,"title":"RAG 技术应用场景","slug":"rag-技术应用场景","link":"#rag-技术应用场景","children":[]},{"level":2,"title":"RAG 标准技术流程","slug":"rag-标准技术流程","link":"#rag-标准技术流程","children":[]},{"level":2,"title":"RAG 与微调的选择","slug":"rag-与微调的选择","link":"#rag-与微调的选择","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"RAG快速开发实战/01｜RAG的场景及技术原理.md","filePath":"RAG快速开发实战/01｜RAG的场景及技术原理.md","lastUpdated":1795533570000}'),n={name:"RAG快速开发实战/01｜RAG的场景及技术原理.md"};function r(p,e,s,o,A,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_01-rag的场景及技术原理" tabindex="-1">01 | RAG的场景及技术原理 <a class="header-anchor" href="#_01-rag的场景及技术原理" aria-label="Permalink to &quot;01 | RAG的场景及技术原理&quot;">​</a></h1><ul><li>本门课程为精品小课，不标配音频</li></ul><p>你好，我是常扬。</p><p>在探讨 RAG 技术之前，我们先看在开发大语言模型（LLM）应用时会遇到的典型场景问题。比如，当设计一个 LLM 问答应用，模型需要处理用户的领域问题时，尽管大模型通常表现出色，但有时提供的答案并不准确，甚至可能出现错误。当用户需要获取实时信息时，模型无法及时提供最新的答案。这种现象在 LLM 应用中较为常见。</p><p>随着 ChatGPT、文心一言、通义千问、LLama 系列等大模型的广泛应用，各行业尝试将其引入业务流程。这些模型在知识、理解和推理方面展现了卓越的能力，在复杂交互场景中表现尤为突出。</p><p>然而，这些模型仍然存在一些无法忽视的局限性。其中，领域知识缺乏是最明显的问题。大模型的知识来源于训练数据，这些数据主要来自公开的互联网和开源数据集，无法覆盖特定领域或高度专业化的内部知识。信息过时则指模型难以处理实时信息，因为训练过程耗时且成本高昂，模型一旦训练完成，就难以获取和处理新信息。</p><p>此外，幻觉问题是另一个显著的局限，模型基于概率生成文本，有时会输出看似合理但实际错误的答案。最后，数据安全性在企业应用中尤为重要，如何在确保数据安全的前提下，使大模型有效利用私有数据进行推理和生成，是一个具有挑战性的问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/1.png" alt=""></a></p><p>为了解决这些问题，仅依赖 LLM 本身是不足的。RAG（Retrieval-Augmented Generation，检索增强生成）技术应运而生。通过将非参数化的外部知识库、文档与大模型相结合，RAG使模型在生成内容之前，能够先检索相关信息，从而弥补模型在知识专业性和时效性上的不足，减少生成不确定性，在确保数据安全的同时，充分利用领域知识和私有数据。</p><p>选择 RAG 而不是直接将所有知识库数据交给大模型处理，主要是因为模型能够处理的 token数有限，输入过多 token 会增加成本。更重要的是，提供少量相关的关键信息能够带来更优质的回答。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/2.png" alt=""></a></p><ul><li>图片来自论文 Retrieval-Augmented Generation for Large Language Models: A Survey</li></ul><p>在图中 RAG 的案例中，用户提出了一个涉及 OpenAI 公司 CEO Sam Altman 的实时问题，询问其在短时间内被解雇和重聘的事件。在不使用 RAG 的情况下，由于大语言模型（LLM）无法访问实时更新的外部信息，用户只能得到一个无法提供有效回答的结果。而通过 RAG 技术，将相关的实时信息转化为知识库内容，并通过检索模块检索到与用户查询高度相关的文档片段，最终生成的回答不仅准确，而且涵盖了实时信息的背景和细节，为用户提供了有价值的解答。</p><h2 id="rag-技术的定义" tabindex="-1">RAG 技术的定义 <a class="header-anchor" href="#rag-技术的定义" aria-label="Permalink to &quot;RAG 技术的定义&quot;">​</a></h2><p>RAG 技术是一种结合检索与生成的自然语言处理（NLP）模型架构。这个技术由 FacebookAI 于 2022 年提出，旨在提升生成式模型在处理开放域问答、对话生成等复杂任务中的性能。RAG 通过引入外部知识库，利用检索模块（Retriever）从大量文档中提取相关信息，并将这些信息传递给生成模块（Generator），从而生成更准确且有用的回答。</p><p>RAG 模型的核心思想在于通过检索与生成的有机结合，弥补大模型在处理领域问题和实时任务时的不足。传统的生成模型在面对复杂问题时，往往由于知识储备不足，生成出错误或无关的回答。而 RAG 通过检索模块获取相关的背景信息，使生成模块能够参考这些信息，从而生成更具可信度和准确性的答案。这种方法不仅增强了生成内容的准确性，还提高了模型在应对特定领域知识和动态信息时的适应能力。</p><h2 id="rag-技术应用场景" tabindex="-1">RAG 技术应用场景 <a class="header-anchor" href="#rag-技术应用场景" aria-label="Permalink to &quot;RAG 技术应用场景&quot;">​</a></h2><p>RAG 技术凭借其将检索与生成相结合的优势，可广泛应用于多个领域和场景，满足了在大模型应用中实时性、高准确性和领域专有知识获取的需求。</p><p>在企业或领域知识管理与问答系统中，RAG 能够实时从企业或领域的私有知识库中检索相关信息，确保生成的回答不仅准确且符合企业内部的最新动态，解决了大模型在处理特定领域知识时的局限性。</p><p>其次，在客户支持与智能客服系统中，RAG 可以动态地将用户的询问与最新的产品信息、客服知识等外部数据相结合，生成的回答更加贴合客户的实际需求，且满足企业要求。</p><p>此外，RAG 在医疗、金融等对数据准确性、时效性要求极高的专业领域中尤为重要。通过实时检索最新的研究成果、市场动态或文档资料，RAG 确保了生成的内容不仅基于最新信息，同时具备领域专有知识的深度分析能力。这些场景中，RAG 的应用有效优化了大模型的固有缺陷，为大模型应用提供了更高的可靠性和场景可落地性。</p><h2 id="rag-标准技术流程" tabindex="-1">RAG 标准技术流程 <a class="header-anchor" href="#rag-标准技术流程" aria-label="Permalink to &quot;RAG 标准技术流程&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/3.png" alt=""></a></p><p>RAG 标准流程由索引（Indexing）、检索（Retriever）和生成（Generation）三个核心阶段组成。</p><ol><li><p>索引阶段，通过处理多种来源多种格式的文档提取其中文本，将其切分为标准长度的文本块（chunk），并进行嵌入向量化（embedding），向量存储在向量数据库（vector database）中。</p></li><li><p>检索阶段，用户输入的查询（query）被转化为向量表示，通过相似度匹配从向量数据库中检索出最相关的文本块。</p></li><li><p>最后生成阶段，检索到的相关文本与原始查询共同构成提示词（Prompt），输入大语言模型（LLM），生成精确且具备上下文关联的回答。</p></li></ol><p>通过这一流程，RAG 实现了检索与生成的有机结合，显著提升了 LLM 在领域任务中的准确性和实时性。</p><p>索引是 RAG 系统的基础环节，包含四个关键步骤。</p><ol><li><p>首先，将各类数据源及其格式（如书籍、教材、领域数据、企业文档等，txt、markdown、doc、ppt、excel、pdf、html、json 等格式）统一解析为纯文本格式。</p></li><li><p>接着，根据文本的语义或文档结构，将文档分割为小而语义完整的文本块（chunks），确保系统能够高效检索和利用这些块中包含的信息。</p></li><li><p>然后，使用文本嵌入模型（embedding model），将这些文本块向量化，生成高维稠密向量，转换为计算机可理解的语义表示。</p></li><li><p>最后，将这些向量存储在向量数据库 (vector database) 中，并构建索引，完成知识库的构建。这一流程成功将外部文档转化为可检索的向量，支撑后续的检索和生成环节。</p></li></ol><p>检索是连接用户查询与知识库的核心环节。首先，用户输入的问题通过同样的文本嵌入模型转换为向量表示，将查询映射到与知识库内容相同的向量空间中。通过相似度度量方法，检索模块从向量数据库中筛选出与查询最相关的前 K 个文本块，这些文本块将作为生成阶段输入的一部分。通过相似性搜索，检索模块有效获取了与用户查询切实相关的外部知识，为生成阶段提供了精确且有意义的上下文支持。</p><p>生成是 RAG 流程中的最终环节，将检索到的相关文本块与用户的原始查询整合为增强提示词（Prompt），并输入到大语言模型（LLM）中。LLM 基于这些输入生成最终的回答，确保生成内容既符合用户的查询意图，又充分利用了检索到的上下文信息，使得回答更加准确和相关，充分使用到知识库中的知识。通过这一过程，RAG 实现了具备领域知识和私有信息的精确内容生成。</p><h2 id="rag-与微调的选择" tabindex="-1">RAG 与微调的选择 <a class="header-anchor" href="#rag-与微调的选择" aria-label="Permalink to &quot;RAG 与微调的选择&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/01/4.png" alt=""></a></p><p>在大模型专业领域场景的应用中，RAG 与微调都是可行的选择，选择的关键在于应用场景更注重外部知识的需求还是模型领域能力的需求。RAG 擅长于高效整合外部知识，尤其在频繁处理实时信息，或者需要回答复杂且依赖外部知识的问题、回答需要具备可解释性需求时，RAG 通过结合检索系统和生成模型，能够实时利用最新信息，生成上下文相关且准确的答案。因此，当应用场景对外部知识的利用有较高需求时，RAG 是更为适宜的方案。</p><p>微调更适合需求稳定、领域知识固定且不需要频繁更新知识库的场景。通过使用特定领域的数据对模型进行深度优化，微调可以提升模型在特定任务或领域中的推理能力，确保输出内容的专业性和一致性。因此，当任务侧重于某一特定领域，并且对实时信息的依赖较低时，微调更能满足这些需求。</p><p>总的来说，RAG 更适用于需要动态响应、频繁更新外部知识的场景，而微调则适合固定领域内的深度优化与推理。当应用场景中既需要利用最新的外部知识，又需要保持高水平的领域推理能力时，可以考虑结合使用 RAG 和微调，以实现最优的性能和效果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课我们探讨了在开发 LLM 应用时所面临的挑战及 RAG 技术价值，介绍了 RAG 技术的定义、应用场景、标准技术流程及与微调的选择。主要内容如下：</p><ol><li><p>LLM 的局限性：LLM 应用场景存在领域知识缺乏、信息过时、幻觉问题和数据安全问题。</p></li><li><p>RAG 技术价值：为了解决这些局限性，RAG 利用检索外部文档提升生成结果质量，充分利用领域知识和私有数据、实时数据，减少生成不确定性，并增强数据安全。</p></li><li><p>RAG 技术定义：通过引入外部知识库，利用检索模型从大量文档中提取相关信息，Prompt组合问题和外部信息，生成更精准且实时的回答。</p></li><li><p>RAG 应用场景：企业或领域知识管理与问答、客户支持与智能客服系统，以及医疗、金融等对数据实时性、精准性要求极高的专业领域等等。</p></li><li><p>RAG 标准流程：索引流程、检索流程、生成流程 3 个关键环节。</p></li><li><p>RAG 与微调的选择：RAG 注重高效整合外部知识，微调适合领域知识固定且对领域推理能力要求高的场景，综合上述需求的场景可以选择 RAG 与微调结合。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这节课我们介绍了 RAG、微调、以及 RAG+ 微调这三种模式。你能不能针对每种模式举出更多适用的场景，并说明该场景选择该模式的原因？期待在留言区看到你的思考，如果你觉得这节课的内容对你有帮助的话，欢迎你分享给其他朋友，我们下节课再见！</p>',40)])])}const R=t(n,[["render",r]]);export{G as __pageData,R as default};
